#!/bin/bash
# goAmnezia pro — словарь EN, модуль lib/import.sh (импорт существующей установки Amnezia)
# shellcheck disable=SC2034,SC2148

I18N[import_scanning]="Looking for Amnezia containers on the server, stopped ones too…"
I18N[import_err_container_name]="Invalid container name: %s (expected amnezia-…)"
I18N[import_err_not_found]="There is no container %s on this server (docker ps -a)"
I18N[import_err_not_adoptable]="Container %s cannot be adopted: %s"
I18N[import_err_already_managed]="Container %s is already ours — it is profile %s"
I18N[import_err_profile_exists]="Container %s maps to profile %s, which is already installed — remove the profile or the container first"
I18N[import_err_conf_read]="Failed to read the config from container %s (/opt/amnezia/awg/*.conf)"
I18N[import_err_conf_parse]="Cannot parse the config of container %s: no server key, subnet or port"
I18N[import_err_container_missing]="Container %s is not running — nothing to reconcile"
I18N[import_reason_unsupported_container]="this container was installed by the Amnezia app and goAmnezia does not support it: the product works with AmneziaWG only"
I18N[import_reason_unknown_kind]="unknown container kind (goAmnezia knows amnezia-awg, amnezia-awg1/2/3)"
I18N[import_reason_managed]="the container is already managed by goAmnezia"
I18N[import_reason_profile_exists]="the profile for this container is already installed"
I18N[import_reason_no_conf]="the container has no AmneziaWG config"
I18N[import_err_docker_unreachable]="Docker does not answer — could not check which Amnezia containers are on the server. Bring the daemon up: systemctl status docker (on a version mismatch — systemctl restart docker)."
I18N[import_reason_managed_as]="already managed by goAmnezia — it is profile %s"
I18N[import_reason_profile_exists_as]="profile %s is already installed in its place — remove the profile or the container first"
I18N[import_reason_app_dns]="the Amnezia app's own DNS: users' DNS queries go through it — left as is, goAmnezia does not manage it"
I18N[import_reason_app_service]="a service container of the Amnezia app (not a VPN) — left as is, goAmnezia does not manage it"
I18N[import_protocol_unknown]="unknown container"
I18N[import_started]="Container %s was stopped — started: users of profile %s can connect again"
I18N[import_start_failed]="Container %s was adopted but did not start: %s. The profile is already under «Protocols»; to start it — «Protocols → profile → Restart» (the watchdog also retries by itself every two minutes)."
I18N[import_start_failed_why]="Docker did not bring it up — most likely another process took its port while the container was stopped"
I18N[import_adopting]="Adopting container %s as profile %s (AmneziaWG %s): the container is not recreated, keys stay"
I18N[import_err_snapshot]="Could not save a snapshot of container %s before adopting — nothing was changed, the container is untouched"
I18N[import_snapshot_saved]="Snapshot of the container before adopting (config, keys, clientsTable): %s"
I18N[import_adopted]="Container %s adopted as profile %s, users added: %s"
I18N[import_adopt_undone]="The adoption did not finish — the record of profile %s was removed from config.json so that a retry is possible"
I18N[import_user_added]="  imported user %s (%s)"
I18N[import_peer_skipped_key]="Peer %s… in the container config skipped: its PublicKey or PresharedKey is not a WireGuard key (44 base64 characters). The user cannot connect with such a key; remove it in the Amnezia app"
I18N[import_peer_skipped_ip]="Peer %s… in the container config skipped: AllowedIPs has no IPv4 address, and a user cannot be adopted without one. Add AllowedIPs for the peer in the container config and run the reconcile again, or remove it in the Amnezia app"
I18N[import_peer_skipped_taken]="Peer %s… in the container config skipped: this key already belongs to a user of another goAmnezia profile, and one key cannot be adopted into two profiles. Remove it in the Amnezia app"
I18N[import_hint_no_privkey]="The adopted users keep their keys in the app, and those keep working, but the server does not have them: they cannot be shown or sent from here. If you still have the vpn:// links or .conf files you sent them, attach them in the user's card («Key» → «Attach the old key») and the keys will be here too. Otherwise reissue the key, and the old one stops working."
I18N[import_adopted_overlap]="Adopted as is: the Amnezia app puts its AmneziaWG containers on one subnet, and the users of both profiles connect as before."
I18N[import_scan_overlap]="subnet %s matches %s — I will adopt it as is and offer to separate them"
I18N[import_reconcile_in_sync]="Profile %s: the keys in the container match the user list"
I18N[import_reconcile_diff]="Profile %s: the container differs from the user list — new keys: %s, missing: %s (the Amnezia app changed the container directly)"
I18N[import_reconcile_applied]="Profile %s: changes adopted — users added: %s, missing keys switched off: %s"
I18N[import_reconcile_ask]="Adopt the changes from the container of profile %s?"
I18N[import_err_ipacket]="Container %s was not adopted: %s Fix the signature packet in the AmneziaWG settings of the Amnezia app and adopt again — the container is untouched."
